gPQ(){return"\u0643\u0644\u0645\u0629 \u0627\u0644\u0645\u0631\u0648\u0631 \u0627\u0644\u062c\u062f\u064a\u062f\u0629"},
gON(){return"\u062a\u0623\u0643\u064a\u062f \u0643\u0644\u0645\u0629 \u0627\u0644\u0645\u0631\u0648\u0631 \u0627\u0644\u062c\u062f\u064a\u062f\u0629"},
gE7(){return"\u064a\u062c\u0628 \u0623\u0646 \u062a\u062a\u0643\u0648\u0646 \u0643\u0644\u0645\u0629 \u0627\u0644\u0645\u0631\u0648\u0631 \u0627\u0644\u062c\u062f\u064a\u062f\u0629 \u0645\u0646 6 \u0623\u062d\u0631\u0641 \u0639\u0644\u0649 \u0627\u0644\u0623\u0642\u0644."},
gE8(){return"\u0643\u0644\u0645\u062a\u0627 \u0627\u0644\u0645\u0631\u0648\u0631 \u0627\u0644\u062c\u062f\u064a\u062f\u062a\u0627\u0646 \u063a\u064a\u0631 \u0645\u062a\u0637\u0627\u0628\u0642\u062a\u064a\u0646."},
gPU(){return"\u062a\u0645 \u062a\u062d\u062f\u064a\u062b \u0643\u0644\u0645\u0629 \u0627\u0644\u0645\u0631\u0648\u0631."},
gE5(){return"\u062d\u0630\u0641 \u062d\u0633\u0627\u0628\u064a"},
gOQ(){return"\u0627\u0637\u0644\u0628 \u062d\u0630\u0641 \u062d\u0633\u0627\u0628\u0643. \u0633\u064a\u062a\u0645 \u062a\u0633\u062c\u064a\u0644 \u062e\u0631\u0648\u062c\u0643 \u0641\u0648\u0631\u0627\u064b \u0648\u0644\u0646 \u062a\u062a\u0645\u0643\u0646 \u0645\u0646 \u062a\u0633\u062c\u064a\u0644 \u0627\u0644\u062f\u062e\u0648\u0644 \u0645\u062c\u062f\u062f\u0627\u064b\u060c \u0648\u062a\u064f\u062d\u0630\u0641 \u0628\u064a\u0627\u0646\u0627\u062a\u0643 \u0627\u0644\u0634\u062e\u0635\u064a\u0629 \u062e\u0644\u0627\u0644 30 \u064a\u0648\u0645\u0627\u064b. \u062a\u0628\u0642\u0649 \u0627\u0644\u0633\u062c\u0644\u0627\u062a \u0627\u0644\u062a\u064a \u064a\u062d\u062a\u0641\u0638 \u0628\u0647\u0627 \u0627\u0644\u0645\u062e\u062a\u0628\u0631 (\u0627\u0644\u062d\u0627\u0644\u0627\u062a \u0648\u0627\u0644\u062f\u0641\u0639\u0627\u062a \u0648\u0627\u0644\u0631\u0648\u0627\u062a\u0628) \u0636\u0645\u0646 \u062f\u0641\u0627\u062a\u0631 \u0627\u0644\u0645\u062e\u062a\u0628\u0631. \u0625\u0630\u0627 \u0643\u0646\u062a \u0627\u0644\u0645\u062f\u064a\u0631 \u0627\u0644\u0648\u062d\u064a\u062f \u0644\u0644\u0645\u062e\u062a\u0628\u0631\u060c \u062a\u0648\u0627\u0635\u0644 \u0645\u0639\u0646\u0627 \u0644\u0625\u063a\u0644\u0627\u0642 \u0627\u0644\u0645\u062e\u062a\u0628\u0631 \u0628\u0627\u0644\u0643\u0627\u0645\u0644."},
gOR(){return"\u062d\u0630\u0641 \u062d\u0633\u0627\u0628\u064a"},
gOS(){return"\u0633\u064a\u062a\u0645 \u062a\u0639\u0637\u064a\u0644 \u062d\u0633\u0627\u0628\u0643 \u0627\u0644\u0622\u0646 \u0648\u062d\u0630\u0641\u0647 \u0646\u0647\u0627\u0626\u064a\u0627\u064b \u062e\u0644\u0627\u0644 30 \u064a\u0648\u0645\u0627\u064b\u060c \u0648\u0644\u0627 \u064a\u0645\u0643\u0646 \u0627\u0644\u062a\u0631\u0627\u062c\u0639 \u0639\u0646 \u0630\u0644\u0643. \u0623\u062f\u062e\u0644 \u0643\u0644\u0645\u0629 \u0627\u0644\u0645\u0631\u0648\u0631 \u0644\u0644\u062a\u0623\u0643\u064a\u062f."},
gQn(){return"\u062d\u0641\u0638 \u0643\u0644\u0645\u0629 \u0627\u0644\u0645\u0631\u0648\u0631 \u0627\u0644\u062c\u062f\u064a\u062f\u0629"},
gOr(){return"\u0627\u0633\u0645 \u0627\u0644\u0641\u0631\u0639"},
