a02(a){return"\u0633\u062a\u064f\u0632\u0627\u0644 \xab"+a+"\xbb \u0645\u0646 \u0645\u0633\u0627\u0631 \u0643\u0644 \u0646\u0648\u0639 \u062d\u0627\u0644\u0629 \u0648\u0645\u0646 \u0627\u0644\u0644\u0648\u062d\u0629. \u062a\u062d\u062a\u0641\u0638 \u0627\u0644\u062d\u0627\u0644\u0627\u062a \u0627\u0644\u0642\u062f\u064a\u0645\u0629 \u0648\u0627\u0644\u0633\u062c\u0644 \u0628\u0627\u0644\u0627\u0633\u0645. \u064a\u0645\u0643\u0646\u0643 \u0627\u0633\u062a\u0639\u0627\u062f\u062a\u0647\u0627 \u0644\u0627\u062d\u0642\u064b\u0627."},
ga01(){return"\u0623\u0631\u0634\u0641\u0629"},
ga0G(){return"\u062d\u0630\u0641 \u0647\u0630\u0647 \u0627\u0644\u0645\u0631\u062d\u0644\u0629 \u0646\u0647\u0627\u0626\u064a\u064b\u0627\u061f"},
a0F(a){return"\u0633\u062a\u064f\u062d\u0630\u0641 \xab"+a+"\xbb \u0646\u0647\u0627\u0626\u064a\u064b\u0627. \u064a\u0639\u0645\u0644 \u0647\u0630\u0627 \u0641\u0642\u0637 \u0625\u0630\u0627 \u0644\u0645 \u062a\u0633\u062a\u062e\u062f\u0645\u0647\u0627 \u0623\u064a \u062d\u0627\u0644\u0629 \u0639\u0644\u0649 \u0627\u0644\u0625\u0637\u0644\u0627\u0642."},
gHH(){return"\u062a\u0645\u062a \u0625\u0632\u0627\u0644\u0629 \u0627\u0644\u0645\u0631\u062d\u0644\u0629."},
ga1P(){return"\u062a\u0645\u062a \u0627\u0633\u062a\u0639\u0627\u062f\u0629 \u0627\u0644\u0645\u0631\u062d\u0644\u0629."},
ga0Q(){return" \xb7 \u0627\u0633\u062a\u0642\u0628\u0627\u0644"},
ga0O(){return" \xb7 \u0646\u0647\u0627\u0626\u064a\u0629"},
ga0P(){return"\u0647\u0630\u0647 \u0647\u064a \u0627\u0644\u0645\u0631\u062d\u0644\u0629 \u0627\u0644\u0623\u062e\u064a\u0631\u0629: \u0627\u0644\u062d\u0627\u0644\u0629 \u0627\u0644\u062a\u064a \u062a\u064f\u0646\u0642\u0644 \u0625\u0644\u064a\u0647\u0627 \u062a\u064f\u062d\u062a\u0633\u0628 \u0645\u064f\u0633\u0644\u064e\u0651\u0645\u0629 \u0648\u0644\u0627 \u062a\u0639\u0648\u062f \u0645\u0646 \u0627\u0644\u062d\u0627\u0644\u0627\u062a \u0627\u0644\u0646\u0634\u0637\u0629. \u0623\u0628\u0642\u0650\u0647\u0627 \u0645\u0631\u062d\u0644\u0629 \u0627\u0644\u062a\u0633\u0644\u064a\u0645. \u0644\u0625\u0636\u0627\u0641\u0629 \u062e\u0637\u0648\u0629 \u0623\u062e\u0631\u0649 \u0623\u0636\u0641 \u0645\u0631\u062d\u0644\u0629 \u062c\u062f\u064a\u062f\u0629 \u0628\u062f\u0644 \u0625\u0639\u0627\u062f\u0629 \u062a\u0633\u0645\u064a\u0629 \u0647\u0630\u0647 \u0627\u0644\u0645\u0631\u062d\u0644\u0629."},
ga1q(){return"\u0646\u0642\u0644 \u0625\u0644\u0649 \u0627\u0644\u0623\u0645\u0627\u0645"},
ga1p(){return"\u0646\u0642\u0644 \u0625\u0644\u0649 \u0627\u0644\u062e\u0644\u0641"},
gHF(){return"\u0646\u0642\u0644 \u0644\u0644\u0623\u0639\u0644\u0649 (\u064a\u0638\u0647\u0631 \u0623\u0648\u0644\u0627\u064b \u0641\u064a \u0625\u062f\u062e\u0627\u0644 \u0627\u0644\u062d\u0627\u0644\u0629)"},
gHE(){return"\u0646\u0642\u0644 \u0644\u0644\u0623\u0633\u0641\u0644"},
ga1M(){return"\u0627\u0644\u0627\u0633\u0645"},
